-- GES / NaCCA 50 + 50 assessment results.
--
-- A GES-standard assessment represents one subject for a class and term; its
-- result stores a class score out of 50 and an exam score out of 50. The total
-- is generated by the database so it cannot drift from its components. Custom
-- assessments keep using the single `score` column, and the trigger below makes
-- the two shapes mutually exclusive.

alter table public.assessments
  add column if not exists framework text not null default 'custom';

alter table public.assessments
  drop constraint if exists assessments_framework_check;

alter table public.assessments
  add constraint assessments_framework_check
  check (framework in ('ges_standard', 'custom'));

-- A GES subject is identified by its official name, not a school-defined
-- subject, and must belong to a term so it can appear on a terminal report.
alter table public.assessments
  drop constraint if exists assessments_ges_shape_check;

alter table public.assessments
  add constraint assessments_ges_shape_check
  check (
    framework <> 'ges_standard'
    or (term_id is not null and subject_id is null and max_score = 100)
  );

comment on column public.assessments.framework is
  'The scoring framework this assessment belongs to: ges_standard (50 + 50) or custom (single score).';

alter table public.assessment_results
  add column if not exists class_score numeric(5, 2),
  add column if not exists exam_score numeric(5, 2),
  add column if not exists total_score numeric(5, 2)
    generated always as (
      case
        when class_score is null or exam_score is null then null
        else class_score + exam_score
      end
    ) stored;

alter table public.assessment_results
  drop constraint if exists assessment_results_class_score_range,
  drop constraint if exists assessment_results_exam_score_range,
  drop constraint if exists assessment_results_total_score_range;

alter table public.assessment_results
  add constraint assessment_results_class_score_range
    check (class_score is null or (class_score >= 0 and class_score <= 50)),
  add constraint assessment_results_exam_score_range
    check (exam_score is null or (exam_score >= 0 and exam_score <= 50)),
  add constraint assessment_results_total_score_range
    check (total_score is null or (total_score >= 0 and total_score <= 100));

comment on column public.assessment_results.class_score is
  'GES continuous class score, out of 50. Null when not marked.';
comment on column public.assessment_results.exam_score is
  'GES terminal examination score, out of 50. Null when not marked.';
comment on column public.assessment_results.total_score is
  'Generated 50 + 50 total, out of 100. Null until both components are marked.';

-- Replace the custom score-ceiling trigger with a framework-aware rule:
--   * custom: only `score`, at most the assessment maximum;
--   * GES:    only class_score/exam_score, each at most 50.
-- The function remains SECURITY DEFINER so the assessment lookup is not blocked
-- by the caller's own policies and fails closed on a missing assessment.
create or replace function public.check_result_score()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_max numeric;
  v_framework text;
begin
  select a.max_score, a.framework
    into v_max, v_framework
  from public.assessments a
  where a.id = new.assessment_id
    and a.school_id = new.school_id;

  if v_max is null then
    raise exception 'assessment not found'
      using errcode = 'foreign_key_violation';
  end if;

  if v_framework = 'ges_standard' then
    if new.score is not null then
      raise exception 'GES results use class_score and exam_score, not score'
        using errcode = 'check_violation';
    end if;
    if new.class_score is not null and new.class_score > 50 then
      raise exception 'class score exceeds 50'
        using errcode = 'check_violation';
    end if;
    if new.exam_score is not null and new.exam_score > 50 then
      raise exception 'exam score exceeds 50'
        using errcode = 'check_violation';
    end if;
  else
    if new.class_score is not null or new.exam_score is not null then
      raise exception 'custom results use score, not class_score/exam_score'
        using errcode = 'check_violation';
    end if;
    if new.score is not null and new.score > v_max then
      raise exception 'score exceeds the assessment maximum'
        using errcode = 'check_violation';
    end if;
  end if;

  return new;
end;
$$;

-- At most one active GES assessment for a subject in a class and term. The
-- coalesce keeps the key usable if a legacy row has no term, although the
-- assessments_ges_shape_check now prevents new GES rows without one.
create unique index if not exists assessments_ges_subject_key
  on public.assessments (
    school_id,
    class_id,
    coalesce(term_id, '00000000-0000-0000-0000-000000000000'::uuid),
    lower(btrim(name))
  )
  where framework = 'ges_standard' and is_active;

create index if not exists assessments_ges_term_idx
  on public.assessments (school_id, class_id, term_id)
  where framework = 'ges_standard';

-- A teacher holds assessment.read but deliberately no academic.read. The GES
-- score-entry screen needs the term list to choose the terminal report period,
-- so this narrowly gated SECURITY DEFINER function returns term options only.
create or replace function public.assessment_terms(target_school_id uuid)
returns table (
  term_id uuid,
  term_name text,
  term_starts_on date,
  term_ends_on date,
  academic_year_id uuid,
  academic_year_name text,
  year_is_current boolean
)
language sql
stable
security definer
set search_path = ''
as $$
  select
    t.id,
    t.name,
    t.starts_on,
    t.ends_on,
    y.id,
    y.name,
    y.is_current
  from public.terms t
  join public.academic_years y
    on y.id = t.academic_year_id
   and y.school_id = t.school_id
  where t.school_id = target_school_id
    and public.has_school_permission(target_school_id, 'assessment.read')
  order by y.starts_on desc, t.starts_on desc;
$$;

comment on function public.assessment_terms(uuid) is
  'Term options for a school, gated by assessment.read. Used by GES score entry; returns no learner data.';

revoke all on function public.assessment_terms(uuid) from public;
revoke all on function public.assessment_terms(uuid) from anon;
grant execute on function public.assessment_terms(uuid) to authenticated;
